     else if (mp_count_bits(mod) != 2048) {
         err = MP_READ_E;
     }
-    else if (*outLen < 256U) {
-        err = BUFFER_E;
-    }
     else if (mp_iseven(mod)) {
         err = MP_VAL;
     }
